new:
if context["saved"] != nil {
    // Run38675722035 reopened Collections: its Pinned Edit is not a
    // single-photo screen. Only the observed OneUp toolbar, containing
    // both exact public control identifiers, permits this shortcut.
    stage = "recognize-restored-single-photo"
    let toolbars = photos.toolbars.matching(NSPredicate(format: "identifier == %@", "Toolbar"))
        .containing(.button, identifier: "PUOneUpBarButtonItemIdentifierEdit")
        .containing(.button, identifier: "PUOneUpBarButtonItemIdentifierToggleDetails")
    guard toolbars.count <= 1 else { throw failure("Restored single-photo toolbar is ambiguous") }
    if toolbars.count == 1 {
        let toolbar = toolbars.element
        let edits = toolbar.buttons.matching(identifier: "PUOneUpBarButtonItemIdentifierEdit")
            .matching(NSPredicate(format: "label == %@", "Edit"))
        let infos = toolbar.buttons.matching(identifier: "PUOneUpBarButtonItemIdentifierToggleDetails")
            .matching(NSPredicate(format: "label == %@", "Info"))
        guard edits.count == 1, infos.count == 1,
              edits.element.isHittable, edits.element.isEnabled,
              infos.element.isHittable, infos.element.isEnabled else {
            throw failure("Restored single-photo controls differ or are not ready")
        }
        try withinBudget()
        // Screen identity is not fixture identity: verify the same
        // exact public filename before any Edit or extension action.
        try verifyPublicFilename()
        return
    }
}
